      }
      [data-theme='dark'] #mofa_advanced_options {
        background: var(--bg-secondary) !important;
        border-left-color: #667eea !important;
        color: var(--text-primary) !important;
      }
      [data-theme='dark'] .viz-results-panel,
      [data-theme='dark'] .viz-control-panel {
        background: var(--bg-tertiary) !important;
        color: var(--text-primary) !important;
      }
      [data-theme='dark'] .viz-header,
      [data-theme='dark'] .viz-control-item label {
        color: var(--text-primary) !important;
      }
      [data-theme='dark'] .viz-stats-container {
        background: var(--bg-secondary) !important;
        color: var(--text-primary) !important;
      }
      [data-theme='dark'] #distStats {
        background: var(--bg-tertiary) !important;
        color: var(--text-primary) !important;
        border-color: var(--border-color) !important;
      }

      /* Make alert-info backgrounds dark-friendly */
      [data-theme='dark'] .alert-info { background: var(--bg-secondary) !important; border-color: var(--border-color) !important; }

      /* Navbar/header light mode blue per backup */
      [data-theme='light'] .navbar, [data-theme='light'] .navbar-default {
        background: #3498db !important;
        border-color: #2c80ba !important;
      }
      [data-theme='light'] .navbar-default .navbar-nav > li > a,
      [data-theme='light'] .navbar .navbar-nav > li > a,
      [data-theme='light'] .navbar-brand { color: #ffffff !important; }

      /* Navbar/header dark mode blue, per preference */
      [data-theme='dark'] .navbar, [data-theme='dark'] .navbar-default {
        background: #3498db !important;
        border-color: #2c80ba !important;
      }
      [data-theme='dark'] .navbar-default .navbar-nav > li > a,
      [data-theme='dark'] .navbar .navbar-nav > li > a,
      [data-theme='dark'] .navbar-brand { color: #ffffff !important; }

      .dark-mode-label {
        color: var(--text-primary) !important;
      }

      /* Plotly dark mode adjustments */
      [data-theme='dark'] .js-plotly-plot {
        background-color: var(--bg-tertiary) !important;
      }

  /* Specific info boxes mentioned to be dark in dark mode */
  [data-theme='dark'] .mlfs-card .alert.alert-info { background: var(--bg-secondary) !important; color: var(--text-primary) !important; border-color: var(--border-color) !important; }
  [data-theme='dark'] .mlfs-card .mt-3 + .alert.alert-info { background: var(--bg-secondary) !important; }
  [data-theme='dark'] .mlfs-card .mlfs-card-header h4, [data-theme='dark'] .mlfs-card .mlfs-card-header { color: var(--text-primary) !important; }

      /* GSEA Plot 2 Settings card and related sections in dark mode */
      [data-theme='dark'] #gseaplot2_controls {
