      [data-theme='dark'] .mlfs-card .alert.alert-warning,
      [data-theme='dark'] .metab-card .alert.alert-warning {
        background-color: var(--bg-tertiary) !important;
        color: var(--text-primary) !important;
        border-color: var(--border-color) !important;
      }

      /* Metabolomics tab card headings – white in dark mode */
      [data-theme='dark'] .metab-card-header,
      [data-theme='dark'] .metab-card-header h4,
      [data-theme='dark'] #metabolomics_navbar .metab-card-header,
      [data-theme='dark'] #metabolomics_navbar .metab-card-header h4 {
        color: #ffffff !important;
      }

      /* Dimred PCA/Download button – no black background on label */
      [data-theme='dark'] .dimred-btn,
      [data-theme='dark'] a.shiny-download-link.dimred-btn,
      [data-theme='dark'] .dimred-card .shiny-download-link {
        background-color: var(--button-primary) !important;
        color: #ffffff !important;
        border-color: var(--button-primary) !important;
      }

      /* Data Visualizations normality / Shapiro–Wilk panel */
      [data-theme='dark'] .viz-shapiro-box,
