      # Dark Mode JavaScript - Consolidated single handler to prevent flickering
      tags$script(HTML("
      (function() {
        // Debounce flag to prevent multiple rapid theme changes
        var themeChangeInProgress = false;
        var lastTheme = null;
        
        function redrawPlots() {
          setTimeout(function() {
            if (window.Plotly) {
              try {
                $('.js-plotly-plot').each(function() { 
                  window.Plotly.redraw(this); 
                });
              } catch (e) {}
            }
          }, 150);
        }
        
        function setCheckboxState(theme) {
          var el = document.getElementById('dark_mode');
          if (el && el.checked !== (theme === 'dark')) {
            el.checked = (theme === 'dark');
          }
        }
        
        function applyTheme(theme, skipShinyNotify) {
          var t = (theme === true || theme === 'dark') ? 'dark' : 'light';
          
          // Prevent duplicate calls for same theme
          if (t === lastTheme && !skipShinyNotify) return;
          if (themeChangeInProgress) return;
          
          themeChangeInProgress = true;
          lastTheme = t;
          
          try {
            document.documentElement.setAttribute('data-theme', t);
            localStorage.setItem('omics-theme', t);
            setCheckboxState(t);
            
            if (!skipShinyNotify && window.Shiny && Shiny.setInputValue) {
              Shiny.setInputValue('dark_mode', t === 'dark', {priority: 'event'});
            }
            
            redrawPlots();
          } catch(e) {
            console.error('Theme apply error:', e);
          }
          
          // Reset debounce flag after a short delay
          setTimeout(function() {
            themeChangeInProgress = false;
          }, 100);
        }
        
        // Expose globally for fallback
        window.__applyTheme = function(checked) { 
          applyTheme(!!checked); 
        };
        
        function initTheme() {
          var saved = 'light';
          try { 
            saved = localStorage.getItem('omics-theme') || 'light'; 
          } catch(e) {}
          applyTheme(saved, true);
          
          // Notify Shiny of initial state after small delay
          setTimeout(function() {
            if (window.Shiny && Shiny.setInputValue) {
              Shiny.setInputValue('dark_mode', saved === 'dark', {priority: 'event'});
            }
          }, 100);
        }
        
        function bindListeners() {
          // Single event handler using delegation - no duplicates
          if (window.jQuery) {
            $(document).off('change.themeToggle', '#dark_mode')
              .on('change.themeToggle', '#dark_mode', function(e) {
                e.stopPropagation();
                applyTheme(this.checked);
              });
          }
          
          // Native fallback
          document.removeEventListener('change', handleThemeChange, true);
          document.addEventListener('change', handleThemeChange, true);
        }
        
        function handleThemeChange(e) {
          if (e && e.target && e.target.id === 'dark_mode') {
            applyTheme(e.target.checked);
          }
        }
        
        // Shiny custom message handler for server-side theme updates
        function registerShinyHandler() {
          if (window.Shiny && window.Shiny.addCustomMessageHandler) {
            try {
              Shiny.addCustomMessageHandler('updateTheme', function(theme) {
                applyTheme(theme, true);
              });
            } catch(e) {}
          }
        }
        
        // Initialize on DOM ready
        if (document.readyState === 'loading') {
          document.addEventListener('DOMContentLoaded', function() {
            initTheme();
            bindListeners();
            registerShinyHandler();
          });
        } else {
          initTheme();
          bindListeners();
          registerShinyHandler();
        }
      })();
    ")),

      # Global functions for UI interactions (available immediately)
      tags$script(HTML("
      // Toggle Element function - shows/hides element by ID
      window.toggleElement = function(elementId) {
        var element = document.getElementById(elementId);
        if (element) {
          if (element.style.display === 'none' || element.style.display === '') {
            element.style.display = 'block';
          } else {
            element.style.display = 'none';
          }
        }
      };

      // Toggle Button Icon function - rotates chevron icon
      window.toggleButtonIcon = function(buttonId) {
        var button = document.getElementById(buttonId);
        if (button) {
          var icon = button.querySelector('i');
          if (icon) {
            if (icon.classList.contains('fa-chevron-right')) {
              icon.classList.remove('fa-chevron-right');
              icon.classList.add('fa-chevron-down');
            } else if (icon.classList.contains('fa-chevron-down')) {
              icon.classList.remove('fa-chevron-down');
              icon.classList.add('fa-chevron-right');
            }
          }
        }
      };
    ")),
      
      tags$script(HTML("
        // Toggle function for collapsible content in associations table
        function toggleCollapse(id) {
          var preview = document.getElementById('preview_' + id);
          var full = document.getElementById('full_' + id);
          var toggle = document.getElementById('toggle_' + id);
          
          if (preview && full && toggle) {
            if (preview.style.display === 'none') {
              // Show preview, hide full
              preview.style.display = 'block';
              full.style.display = 'none';
              toggle.textContent = 'Show more';
            } else {
              // Hide preview, show full
              preview.style.display = 'none';
              full.style.display = 'block';
              toggle.textContent = 'Show less';
            }
          }
        }
