      tags$script(HTML("
      // Initialize tooltips on page load
      $(document).ready(function(){
        // Function to initialize tooltips
        function initTooltips() {
          $('[data-toggle=\"tooltip\"]').tooltip('dispose').tooltip();
        }

        // Initial tooltip initialization
        initTooltips();

        // Re-initialize tooltips whenever the DOM is updated (for dynamic content)
        var observer = new MutationObserver(function(mutations) {
          var shouldReinit = false;
          mutations.forEach(function(mutation) {
            if (mutation.type === 'childList' && mutation.addedNodes.length > 0) {
              for (var i = 0; i < mutation.addedNodes.length; i++) {
                var node = mutation.addedNodes[i];
                if (node.nodeType === 1) { // Element node
                  if ($(node).find('[data-toggle=\"tooltip\"]').length > 0 ||
                      $(node).is('[data-toggle=\"tooltip\"]')) {
                    shouldReinit = true;
                    break;
                  }
                }
              }
            }
          });

          if (shouldReinit) {
            setTimeout(initTooltips, 100);
          }
        });

        // Observe the entire document for changes
        observer.observe(document.body, {
          childList: true,
          subtree: true
        });

        // For Shiny-specific updates
        $(document).on('shiny:value', function(event) {
          setTimeout(initTooltips, 150);
        });

        // For tab changes
        $('a[data-toggle=\"tab\"]').on('shown.bs.tab', function (e) {
          setTimeout(initTooltips, 150);
        });

        // For navbar changes
        $('.navbar-nav a').on('shown.bs.tab', function (e) {
          setTimeout(initTooltips, 150);
        });

        // Enhanced color picker z-index management
        $(document).on('click', '.colourpicker-input, .colourpicker-button', function() {
          // Temporarily boost z-index for active color picker
          setTimeout(function() {
            $('.colourpicker-palette, .colourpicker-popup').css('z-index', '999999');
          }, 50);
        });

        // Reset z-index when color picker is closed
        $(document).on('click', function(e) {
          if (!$(e.target).closest('.colourpicker-palette, .colourpicker-popup, .colourpicker-input, .colourpicker-button').length) {
            $('.colourpicker-palette, .colourpicker-popup').css('z-index', '99999');
          }
        });
      });
    ")),
      
