            } else if (bgSource === 'full_dataset') {
              $('#proteomics_topgo_manual_input_container').slideUp(200);
              $('#proteomics_topgo_full_dataset_container').slideDown(200);
            }
          }
        }

        // Debounced update function to prevent excessive calls
        var updateUI = debounce(function() {
          updateGOOntologyVisibility();
          updateMSigDBVisibility();
          updateGSEAVisibility();
          updatePlotTypeControlsVisibility();
          updateNetworkTypeOptions();
          updateNetworkViewControls();
          updateGraphvizOptionsVisibility();
          updateGProfilerCustomBackgroundVisibility();
          updateGProfilerBackgroundSourceVisibility();
