        }, 150);

        // Separate function to update network-related controls when tool/analysis changes
        var updateNetworkRelated = debounce(function() {
          updateNetworkTypeOptions();
          updateNetworkViewControls();
        }, 100);

        // Simple debounce function
        function debounce(func, wait) {
          var timeout;
          return function executedFunction() {
            var context = this;
            var args = arguments;
            var later = function() {
              timeout = null;
              func.apply(context, args);
            };
            clearTimeout(timeout);
            timeout = setTimeout(later, wait);
          };
        }

        // Bind events with minimal overhead
        $(document)
          .on('change', '#proteomics_plot_type, #proteomics_tool, #proteomics_cp_analysis', function() {
            updateUI();
            updateNetworkRelated();
