          if (tool !== 'topgo') {
            $('#proteomics_run').prop('disabled', false).addClass('btn-primary').removeClass('btn-secondary');
            $('#topgo_compatibility_warning').remove();
          }
        });

        // Initial setup
        setTimeout(function() {
          updateUI();
          updateNetworkRelated();
        }, 100);

        // Performance optimization: cache selectors
        var $proteomicsTabs = $('#proteomics_tabs');
        var $plotType = $('#proteomics_plot_type');
        var $tool = $('#proteomics_tool');

        // Optimize tab switching performance
        $proteomicsTabs.on('show.bs.tab', function(e) {
