      // topGO algorithm-statistic validation and dynamic updates
      function validateTopGOCombination() {
        var algorithm = $('#proteomics_topgo_algorithm').val();
        var statistic = $('#proteomics_topgo_statistic').val();
        var isValidCombination = true;
        var warningMessage = '';

        // Define valid combinations based on topGO documentation
        // Fisher works with ALL algorithms
        // Weight algorithm only works with Fisher
        // Other statistics work with classic, elim, weight01 but NOT parentchild or weight
        var validCombinations = {
          'fisher': ['classic', 'elim', 'weight', 'weight01', 'parentchild'],
          'ks': ['classic', 'elim', 'weight01'],
          't': ['classic', 'elim', 'weight01'],
          'globaltest': ['classic', 'elim', 'weight01'],
          'sum': ['classic', 'elim', 'weight01']
        };

        if (statistic && algorithm) {
          isValidCombination = validCombinations[statistic] &&
                              validCombinations[statistic].includes(algorithm);

          if (!isValidCombination) {
            warningMessage = 'Warning: ' + algorithm + ' algorithm is not compatible with ' +
                           statistic + ' statistic. Valid algorithms for ' + statistic + ': ' +
                           validCombinations[statistic].join(', ');
          }
        }

        // Show/hide warning message and disable/enable Run Analysis button
        $('#topgo_compatibility_warning').remove();
        if (!isValidCombination && warningMessage) {
          var warningHtml = '<div id=\"topgo_compatibility_warning\" class=\"alert alert-warning\" style=\"margin-top: 10px;\">' +
                           '<i class=\"fa fa-exclamation-triangle\"></i> ' + warningMessage + '</div>';
          $(warningHtml).insertAfter('#proteomics_topgo_statistic').closest('.form-group');

          // Disable Run Analysis button for invalid combinations
          $('#proteomics_run').prop('disabled', true).addClass('btn-secondary').removeClass('btn-primary');
        } else {
          // Enable Run Analysis button for valid combinations
          $('#proteomics_run').prop('disabled', false).addClass('btn-primary').removeClass('btn-secondary');
        }

        return isValidCombination;
      }

      // Update statistic choices based on selected algorithm
      function updateTopGOStatisticChoices() {
        var algorithm = $('#proteomics_topgo_algorithm').val();
        var currentStatistic = $('#proteomics_topgo_statistic').val();

        // Define which statistics work with each algorithm
        // Fisher works with ALL algorithms
        // Weight algorithm only works with Fisher
        // Other statistics work with classic, elim, weight01 but NOT parentchild or weight
        var algorithmStatistics = {
          'classic': ['fisher', 'ks', 't', 'globaltest', 'sum'],
          'elim': ['fisher', 'ks', 't', 'globaltest', 'sum'],
          'weight': ['fisher'],  // Only fisher works with weight
          'weight01': ['fisher', 'ks', 't', 'globaltest', 'sum'],
          'parentchild': ['fisher']  // Only fisher works with parentchild
        };

        var availableStats = algorithmStatistics[algorithm] || [];
        var statisticChoices = {
          'fisher': 'Fisher Exact Test',
          'ks': 'Kolmogorov-Smirnov Test',
          't': 't-test',
          'globaltest': 'Global Test',
          'sum': 'Sum Test'
        };

        // Update the select options
        var selectElement = $('#proteomics_topgo_statistic');
        selectElement.empty();

        availableStats.forEach(function(stat) {
          var option = new Option(statisticChoices[stat], stat);
          selectElement.append(option);
        });

        // Restore previous selection if still valid, otherwise select first option
        if (availableStats.includes(currentStatistic)) {
          selectElement.val(currentStatistic);
        } else {
          selectElement.val(availableStats[0]);
        }

        selectElement.trigger('change');

        // Validate the new combination
        setTimeout(function() {
          validateTopGOCombination();
        }, 50);
      }

      // Bind event handlers for topGO validation
      $(document).on('change', '#proteomics_topgo_algorithm', function() {
        updateTopGOStatisticChoices();
        setTimeout(validateTopGOCombination, 100);
      });

      $(document).on('change', '#proteomics_topgo_statistic', function() {
        setTimeout(validateTopGOCombination, 100);
      });

      // Validation on Run Analysis button click
      $(document).on('click', '#proteomics_run', function(e) {
        var tool = $('#proteomics_tool').val();

        // Only validate for topGO
        if (tool === 'topgo') {
          var isValidCombination = validateTopGOCombination();

          if (!isValidCombination) {
            e.preventDefault(); // Prevent the button click from proceeding
            e.stopPropagation();

            // Show error message
            var algorithm = $('#proteomics_topgo_algorithm').val();
            var statistic = $('#proteomics_topgo_statistic').val();

            alert('Invalid topGO combination: ' + algorithm + ' algorithm is not compatible with ' +
                  statistic + ' statistic. Please select a valid combination before running the analysis.');

            return false;
          }
        }
      });

