          $('#impute_knn_options, #impute_min_options, #impute_minprob_options').hide();
          if (imputationMethod === 'knn') {
            $('#impute_knn_options').show();
          } else if (imputationMethod === 'min') {
            $('#impute_min_options').show();
          } else if (imputationMethod === 'minprob') {
            $('#impute_minprob_options').show();
          }

          // Filter before imputation options
