            if (includeCovariates && sigMethod === 'anova') {
              $('#anova_covariate_selection_ui').show();
            } else {
              $('#anova_covariate_selection_ui').hide();
            }
            // Update post-hoc dropdown client-side to avoid server round-trip delay
            var choices = window.OMICS_POSTHOC && window.OMICS_POSTHOC[sigMethod];
            if (choices) {
              var $sel = $('#posthoc_method');
              if ($sel.length) {
                // Update the label client-side
                var $label = $('label[for=\"posthoc_method\"]');
                if ($label.length) {
                  $label.text('Post-hoc Test:');
                }
                
                // Check if selectize is used (Shiny default)
                var selectize = $sel[0].selectize;
                if (selectize) {
                  // Update selectize instance
                  var cur = selectize.getValue();
                  selectize.clearOptions();
                  for (var i = 0; i < choices.length; i++) {
                    selectize.addOption({value: choices[i].v, label: choices[i].l});
                  }
                  selectize.refreshOptions(false);
                  var valid = choices.some(function(c) { return c.v === cur; });
                  var newVal = valid ? cur : (sigMethod === 'anova' ? 'tukey' : 'dunn');
                  selectize.setValue(newVal, true); // true = silent, don't trigger change event yet
                  if (typeof Shiny !== 'undefined' && Shiny.setInputValue) {
                    Shiny.setInputValue('posthoc_method', newVal, {priority: 'event'});
                  }
                } else {
                  // Fallback for non-selectize
                  var cur = $sel.val();
                  $sel.empty();
                  for (var i = 0; i < choices.length; i++) {
                    $sel.append($('<option></option>').attr('value', choices[i].v).text(choices[i].l));
                  }
                  var valid = choices.some(function(c) { return c.v === cur; });
                  if (valid) { $sel.val(cur); } else { $sel.val(sigMethod === 'anova' ? 'tukey' : 'dunn'); }
                  if (typeof Shiny !== 'undefined' && Shiny.setInputValue) {
                    Shiny.setInputValue('posthoc_method', $sel.val(), {priority: 'event'});
                  }
                }
              }
            }
