            $('#viz_info_edger_limma').show();
          } else if (sigMethod === 'deseq2') {
            $('#viz_info_deseq2').show();
          }

          // Data visualization option panels
          var vizPlotType = $('#viz_plot_type').val();
          $('#viz_transform_options, #viz_grouping_options, #viz_correlation_options, #viz_histogram_options, #viz_ordination_options, #viz_variance_options, #viz_distance_options').hide();

          if (['hist', 'density'].includes(vizPlotType)) {
            $('#viz_transform_options').show();
          }
          if (['boxplot', 'qq'].includes(vizPlotType)) {
