          }
          if (vizPlotType === 'corr') {
            $('#viz_correlation_options').show();
          }
          if (vizPlotType === 'hist') {
            $('#viz_histogram_options').show();
          }
          if (['mds', 'pca'].includes(vizPlotType)) {
            $('#viz_ordination_options').show();
          }
          if (['bcv', 'meanvar', 'ql_disp'].includes(vizPlotType)) {
            $('#viz_variance_options').show();
          }
          if (vizPlotType === 'sample_dist') {
            $('#viz_distance_options').show();
          }
          
          // ==================== QC SIGNAL DRIFT CORRECTION OPTIONS ====================
          // QC Drift correction main toggle
          var qcDriftEnabled = $('input[name=\\'qc_drift_enabled\\']:checked').val();
          if (qcDriftEnabled === 'yes') {
            $('#qc_drift_options').show();
          } else {
            $('#qc_drift_options').hide();
          }
          
          // QC identification method options
          var qcIdMethod = $('#qc_identification_method').val();
          $('#qc_auto_detect_info, #qc_metadata_options, #qc_pattern_options').hide();
          if (qcIdMethod === 'auto') {
