          // Run order source options
          var runOrderSource = $('#run_order_source').val();
          $('#run_order_metadata_options, #run_order_pattern_options').hide();
          if (runOrderSource === 'metadata') {
            $('#run_order_metadata_options').show();
          } else if (runOrderSource === 'names') {
