          // Drift correction method-specific options
          var driftMethod = $('#qc_drift_method').val();
          $('#qc_loess_options, #qc_svr_options, #qc_serrf_options, #qc_spline_options').hide();
          if (driftMethod === 'qc_rlsc') {
