            $('#qc_svr_options').show();
          } else if (driftMethod === 'serrf') {
            $('#qc_serrf_options').show();
          } else if (driftMethod === 'spline') {
            $('#qc_spline_options').show();
          }
          
          // Per-batch correction options
          var perBatchCorrection = $('#qc_correct_per_batch').is(':checked');
          if (perBatchCorrection) {
            $('#qc_batch_column_options').show();
          } else {
            $('#qc_batch_column_options').hide();
          }
          // ==================== END QC SIGNAL DRIFT CORRECTION OPTIONS ====================
        }

        // Bind event listeners to all relevant inputs
        $(document).on('change', 'input[name=\\'missing_value_strategy\\'], #imputation_method, #filter_before_impute, #normalization, #sig_method, input[name=\\'batch_correction_enabled\\'], #viz_batch_enable, #rots_parallel, #rots_mode, #lmrots_parallel, #lmerots_parallel, input[name=\\'bootstrap_enabled\\'], #bootstrap_parallel, #viz_plot_type, input[name=\\'qc_drift_enabled\\'], #qc_identification_method, #run_order_source, #qc_drift_method, #qc_correct_per_batch', updateDataTabVisibility);
        
        // Handle ANOVA covariate checkbox change
        $(document).on('change', '#anova_include_covariates', function() {
          var sigMethod = $('#sig_method').val();
          if (sigMethod === 'anova') {
            var includeCovariates = $(this).is(':checked');
            if (includeCovariates) {
              $('#anova_covariate_selection_ui').show();
            } else {
              $('#anova_covariate_selection_ui').hide();
            }
          }
        });

        // Also bind to change events for radio buttons specifically
        $(document).on('change', 'input[type=\\'radio\\']', function() {
          setTimeout(updateDataTabVisibility, 50);
        });

        // Handle Custom NA Values checkbox
        $(document).on('change', '#enable_custom_na', function() {
          if (this.checked) {
            $('#custom_na_input_div').show();
          } else {
            $('#custom_na_input_div').hide();
          }
        });

        // Initial update
        updateDataTabVisibility();

        // Update when page loads and when tabs change
        setTimeout(updateDataTabVisibility, 500);
        setTimeout(updateDataTabVisibility, 1000);

        // Custom message handlers for server-controlled elements
        if (window.Shiny) {
          Shiny.addCustomMessageHandler('updateBootstrapResults', function(hasResults) {
            if (hasResults) {
              $('#bootstrap_results_content').show();
              $('#bootstrap_results_no_content').hide();
            } else {
              $('#bootstrap_results_content').hide();
              $('#bootstrap_results_no_content').show();
            }

            // Also update the info panel in Statistics Results tab
            var bootstrapEnabled = $('input[name=\\'bootstrap_enabled\\']:checked').val();
            if (bootstrapEnabled === 'yes' && hasResults) {
              $('#bootstrap_results_info').show();
            } else {
              $('#bootstrap_results_info').hide();
            }
          });

          Shiny.addCustomMessageHandler('updateImputationDetails', function(hasDetails) {
            if (hasDetails) {
              $('#imputation_details').show();
            } else {
              $('#imputation_details').hide();
            }
          });
        }
      });
