      # Color Picker Show/Hide JavaScript
      tags$script(HTML("
      $(document).ready(function() {
        // Function to handle color picker visibility with smooth animation
        function toggleColorPickers(checkboxId, controlsId) {
          var checkbox = $('#' + checkboxId);
          var controls = $('#' + controlsId);

          if (checkbox.is(':checked')) {
            controls.removeClass('hidden');
            controls.css({
              'opacity': '1',
              'max-height': '1000px',
              'padding': '',
              'margin': ''
            });
          } else {
            controls.addClass('hidden');
            controls.css({
              'opacity': '0',
              'max-height': '0',
              'padding': '0',
              'margin': '0'
            });
          }
        }

        // Initialize color pickers as hidden
        $('#pca_color_controls, #spca_color_controls, #umap_color_controls, #tsne_color_controls').addClass('hidden').css({
          'opacity': '0',
          'max-height': '0',
          'padding': '0',
          'margin': '0'
        });

        // Handle PCA custom colors checkbox
        $(document).on('change', '#pca_custom_colors', function() {
          toggleColorPickers('pca_custom_colors', 'pca_color_controls');
        });

        // Handle sPCA custom colors checkbox
        $(document).on('change', '#spca_custom_colors', function() {
          toggleColorPickers('spca_custom_colors', 'spca_color_controls');
        });

        // Handle UMAP custom colors checkbox
        $(document).on('change', '#umap_custom_colors', function() {
          toggleColorPickers('umap_custom_colors', 'umap_color_controls');
        });

        // Handle t-SNE custom colors checkbox
        $(document).on('change', '#tsne_custom_colors', function() {
          toggleColorPickers('tsne_custom_colors', 'tsne_color_controls');
        });

        // Handle initial state based on checkbox values
        setTimeout(function() {
          if ($('#pca_custom_colors').is(':checked')) {
            toggleColorPickers('pca_custom_colors', 'pca_color_controls');
          }
          if ($('#spca_custom_colors').is(':checked')) {
            toggleColorPickers('spca_custom_colors', 'spca_color_controls');
          }
          if ($('#umap_custom_colors').is(':checked')) {
            toggleColorPickers('umap_custom_colors', 'umap_color_controls');
          }
          if ($('#tsne_custom_colors').is(':checked')) {
            toggleColorPickers('tsne_custom_colors', 'tsne_color_controls');
          }
        }, 500);
      });
    "))
    ,
    tags$script(HTML(" 
      $(document).ready(function() {
        var menuLocked = false;
        var hideTimer = null;

        function getMainNavbar() {
          return $('body > .navbar').first();
        }

        function ensureMainNavbarClass() {
          var $navbar = getMainNavbar();
          if ($navbar.length) {
            $navbar.addClass('main-level-navbar');
            updateMainMenuMetrics();
          }
          return $navbar;
        }

        function updateMainMenuMetrics() {
          var $navbar = getMainNavbar();
          var navbarHeight = 56;

          if ($navbar.length) {
            var measuredHeight = $navbar.outerHeight();
            if (measuredHeight && measuredHeight > 0) {
              navbarHeight = Math.ceil(measuredHeight);
            }
          }

          document.documentElement.style.setProperty('--main-menu-height', navbarHeight + 'px');
        }

        function showMainMenu() {
          ensureMainNavbarClass();
          updateMainMenuMetrics();
          $('body').addClass('main-menu-visible');
        }

        function hideMainMenu() {
          if (menuLocked) return;
          $('body').removeClass('main-menu-visible');
        }

        function clearHideTimer() {
          if (hideTimer) {
            clearTimeout(hideTimer);
            hideTimer = null;
          }
        }

        function scheduleHideMenu() {
          if (menuLocked) return;
          clearHideTimer();
          hideTimer = setTimeout(function() {
            hideMainMenu();
          }, 140);
        }

        function setMenuLockState(locked) {
          menuLocked = locked;
          var $lockIcon = $('#main_menu_lock_btn i');
          var $lockBtn = $('#main_menu_lock_btn');

          $lockBtn.toggleClass('locked', locked);
          $lockIcon.toggleClass('fa-lock', locked);
          $lockIcon.toggleClass('fa-unlock-alt', !locked);

          if (locked) {
            $('body').addClass('main-menu-locked');
            showMainMenu();
          } else {
            $('body').removeClass('main-menu-locked');
            hideMainMenu();
          }
        }

        ensureMainNavbarClass();
        updateMainMenuMetrics();
        hideMainMenu();

        $(window).on('resize', function() {
          updateMainMenuMetrics();
        });

        $(document).on('mouseenter', '#main_menu_handle', function() {
          clearHideTimer();
          showMainMenu();
        });

        $(document).on('mouseleave', '#main_menu_handle', function() {
          scheduleHideMenu();
        });

        $(document).on('mouseenter', 'body > .navbar.main-level-navbar', function() {
          clearHideTimer();
          showMainMenu();
        });

        $(document).on('mouseleave', 'body > .navbar.main-level-navbar', function() {
          scheduleHideMenu();
        });

        $(document).on('click', '#main_menu_handle', function(e) {
          e.preventDefault();
          if ($('body').hasClass('main-menu-visible')) {
            hideMainMenu();
          } else {
            showMainMenu();
          }
        });

        $(document).on('click', '#main_menu_lock_btn', function(e) {
          e.preventDefault();
          e.stopPropagation();
          setMenuLockState(!menuLocked);
        });

        $(document).on('shown.bs.tab', function() {
          ensureMainNavbarClass();
          updateMainMenuMetrics();
        });
      });
    "))
