    tabPanel(
      "ML Feature Selection",
      fluidPage(
        tags$div(class = "glyco-header",
                 h4("ML Feature Selection", class = "glyco-main-title"),
                 p("Select and visualize important features using machine learning methods", class = "glyco-subtitle")
        ),
        fluidRow(
          column(
            3,
            div(class = "mlfs-card",
                div(class = "mlfs-card-header",
                    h4(icon("cogs", class = "mlfs-feature-icon"), "Feature Selection Settings"),
                    shinyBS::tipify(icon("question-circle", class = "mlfs-tooltip"),
                                    "Choose a feature selection method and configure its parameters")
                ),
                
                # Feature Filtering Section
                selectInput(
                  "feature_filtering_method", "Filtering Method:",
                  choices = c(
                    "None" = "none",
                    "Variance Threshold" = "variance",
                    "Correlation Filter" = "correlation",
                    "PCA Top N Features" = "pca"
                  ),
                  selected = "none",
                  width = "100%"
                ),
                
                # Variance Threshold Parameters
                div(id = "variance_filtering_params", style = "display: none;",
                    numericInput("feature_filtering_variance", "Variance Threshold:", min = 0, max = 1, value = 0.01, step = 0.01, width = "100%"),
                    helpText("Features with variance below this threshold will be removed", style = "font-size: 0.85em; color: #666;")
                ),
                
                # Correlation Filter Parameters
                div(id = "correlation_filtering_params", style = "display: none;",
                    numericInput("feature_filtering_corr_cutoff", "Correlation Cutoff (|r|):", min = 0, max = 1, value = 0.1, step = 0.01, width = "100%"),
                    helpText("Select features with absolute correlation with target above this threshold", style = "font-size: 0.85em; color: #666;")
                ),
                
                # PCA Top N Features Parameters
                div(id = "pca_filtering_params", style = "display: none;",
                    div(class = "alert alert-info", style = "margin-bottom: 10px; font-size: 0.9em;",
                        p("Uses the Top N features selected from the PCA tab. Make sure to run PCA analysis and make features global first.",
                          style = "margin-bottom: 0;")
                    ),
                    # Dynamic PCA status indicator
                    uiOutput("mlfs_pca_status"),
                    helpText("This filtering method will use the pre-selected PCA features from the Dimensionality Reduction tab.",
                             style = "font-size: 0.85em; color: #666;")
                ),
                
                # ML Feature Selection Section
                selectInput(
                  "feature_selection_method", "ML Feature Selection Method:",
                  choices = c(
                    "LASSO/ElasticNet" = "lasso",
                    "Random Forest Importance" = "rf",
                    "Permutation Importance" = "permutation",
                    "Recursive Feature Elimination" = "rfe",
                    "Boruta" = "boruta"
                  ),
                  selected = "lasso",
                  width = "100%"
                ),
                
                # Enhanced LASSO/ElasticNet Parameters
                div(id = "lasso_params",
                    conditionalPanel(
                      condition = "input.feature_selection_method == 'lasso'",
                      
                      # Information Card
                      div(class = "alert alert-info", style = "margin-bottom: 15px;",
                          h5(icon("info-circle"), "LASSO/ElasticNet Configuration"),
                          p("LASSO (L1 regularization) and ElasticNet (L1+L2 regularization) perform automatic feature selection by shrinking coefficients. Alpha controls the balance between L1 (feature selection) and L2 (grouping effect) penalties.")
                      ),
                      
                      # Family/Problem Type Selection
                      selectInput("glmnet_family", "Problem Type:",
                                  choices = c(
                                    "Binary Classification" = "binomial",
                                    "Multi-class Classification" = "multinomial",
                                    "Continuous Regression" = "gaussian",
                                    "Count Data (Poisson)" = "poisson",
                                    "Cox Survival" = "cox",
                                    "Multiple Response Gaussian" = "mgaussian",
                                    "Grouped Multinomial" = "grouped_multinomial"
                                  ),
                                  selected = "binomial",
                                  width = "100%"),
                      
                      # Binary Classification group selection (replaces pairwise checkbox)
                      div(id = "binary_group_selection",
                          conditionalPanel(
                            condition = "input.glmnet_family == 'binomial'",
                            div(class = "binary-group-card", style = "margin: 10px 0; padding: 10px; border-radius: 5px;",
                                h6("Group Selection for Binary Classification", style = "margin-bottom: 10px; font-weight: 600;"),
                                fluidRow(
                                  column(6, selectizeInput("mlfsGroup1", "Group 1:", choices = NULL, width = "100%")),
                                  column(6, selectizeInput("mlfsGroup2", "Group 2:", choices = NULL, width = "100%"))
                                ),
                                helpText("Select two groups for binary classification comparison.")
                            )
                          )
                      ),
                      
                      # Multi-class groups selection (optional subset)
                      conditionalPanel(
                        condition = "input.glmnet_family == 'multinomial' || input.glmnet_family == 'grouped_multinomial'",
                        selectizeInput("lasso_groups_multi", "Groups (blank = all):", choices = NULL, multiple = TRUE, width = "100%"),
                        helpText("Select specific groups for multi-class analysis, or leave blank to include all groups.")
                      ),
                      
                      # Essential Parameters Section - Clean and organized
                      div(style = "margin: 15px 0;",
                          
                          # Alpha parameter (most important)
                          div(style = "margin-bottom: 15px;",
                              checkboxInput("autotune_alpha", "Auto-tune Alpha (Grid Search)", value = FALSE, width = "100%"),
                              helpText("When enabled, automatically finds the best alpha value through cross-validation"),
                              
                              # Manual alpha selection (shown when autotune is OFF)
                              div(id = "manual_alpha_options",
                                  sliderInput("feature_selection_alpha",
                                              "Regularization Type (Alpha):",
                                              min = 0, max = 1, value = 1, step = 0.05,
                                              width = "100%"),
                                  helpText("1.0: Pure LASSO (L1) | 0.5: Balanced Elastic Net | 0.0: Ridge (L2)")
                              ),
                              
