    # ==============================================================================
    # MULTI-OMICS INTEGRATION TAB
    # ==============================================================================
    tabPanel(
      "Multi-Omics Integration",
      icon = icon("layer-group"),
      fluidPage(class = "multiomics-tab-content",
        # Header
        div(class = "glyco-header",
            h4("Multi-Omics Data Integration", class = "glyco-main-title"),
            p("Integrate and analyze multiple omics datasets simultaneously to uncover cross-layer biological insights", class = "glyco-subtitle")
        ),
        
        # CSS for Multi-Omics Tab
        tags$style(HTML("
        .multiomics-upload-card {
          background: white;
          border-radius: 8px;
          padding: 12px;
          margin-bottom: 12px;
          box-shadow: 0 2px 8px rgba(0,0,0,0.1);
          border-left: 3px solid #667eea;
          transition: all 0.3s ease;
        }

        .multiomics-upload-card:hover {
          box-shadow: 0 4px 12px rgba(102, 126, 234, 0.2);
          transform: translateY(-2px);
        }

        .multiomics-upload-card.uploaded {
          border-left-color: #10b981;
          background: linear-gradient(to right, #f0fdf4 0%, white 50%);
        }

        .multiomics-upload-card.error {
          border-left-color: #ef4444;
          background: linear-gradient(to right, #fef2f2 0%, white 50%);
        }

        .dataset-header {
          display: flex;
          align-items: center;
          justify-content: space-between;
          margin-bottom: 10px;
        }

        .dataset-title {
          font-size: 1em;
          font-weight: 600;
          color: #2d3748;
          display: flex;
          align-items: center;
          gap: 8px;
        }

        .dataset-status {
          padding: 3px 8px;
          border-radius: 12px;
          font-size: 0.75em;
          font-weight: 500;
        }

        .status-pending {
          background: #fef3c7;
          color: #92400e;
        }

        .status-uploaded {
          background: #d1fae5;
          color: #065f46;
        }

        .status-error {
          background: #fee2e2;
          color: #991b1b;
        }

        /* Compact form controls for dataset upload */
        .multiomics-upload-card .form-group {
          margin-bottom: 10px;
        }

        .multiomics-upload-card label {
          font-size: 0.95em;
          font-weight: 500;
          margin-bottom: 3px;
        }

        .multiomics-upload-card .form-control,
        .multiomics-upload-card .selectize-input {
          font-size: 0.9em;
          padding: 6px 12px;
          height: 34px;
        }

        .multiomics-upload-card .btn-file {
          font-size: 0.85em;
          padding: 6px 12px;
          height: 34px;
        }

        .sample-match-matrix {
          background: white;
          border-radius: 8px;
          padding: 15px;
          margin-top: 15px;
          border: 1px solid #e5e7eb;
        }

        .integration-method-card {
          background: white;
          border-radius: 10px;
          padding: 20px;
          margin-bottom: 15px;
          border: 2px solid #e5e7eb;
          cursor: pointer;
          transition: all 0.3s ease;
        }

        .integration-method-card:hover {
          border-color: #667eea;
          box-shadow: 0 4px 12px rgba(102, 126, 234, 0.15);
        }

        .integration-method-card.selected {
          border-color: #667eea;
          background: linear-gradient(135deg, #f0f4ff 0%, white 100%);
          box-shadow: 0 4px 12px rgba(102, 126, 234, 0.2);
        }

        .method-title {
          font-size: 1.1em;
          font-weight: 600;
          color: #667eea;
          margin-bottom: 8px;
        }

        .method-description {
          color: #6b7280;
          font-size: 0.95em;
          line-height: 1.5;
        }

        .method-badge {
          display: inline-block;
          padding: 3px 10px;
          border-radius: 12px;
          font-size: 0.75em;
          font-weight: 600;
          margin-right: 8px;
          margin-top: 8px;
        }

        .badge-supervised {
          background: #dbeafe;
          color: #1e40af;
        }

        .badge-unsupervised {
          background: #fef3c7;
          color: #92400e;
        }

        .badge-network {
          background: #e0e7ff;
          color: #3730a3;
        }

        .badge-recommended {
          background: #d1fae5;
          color: #065f46;
        }

        .multiomics-results-panel {
          background: white;
          border-radius: 12px;
          padding: 25px;
          box-shadow: 0 2px 8px rgba(0,0,0,0.1);
          min-height: 400px;
        }

        [data-theme='dark'] .multiomics-upload-card,
        [data-theme='dark'] .integration-method-card,
        [data-theme='dark'] .multiomics-results-panel {
          background: var(--bg-secondary) !important;
          color: var(--text-primary) !important;
          border-color: var(--border-color) !important;
        }

        [data-theme='dark'] .multiomics-upload-card.uploaded {
          background: linear-gradient(to right, #064e3b 0%, var(--bg-secondary) 50%);
        }

        [data-theme='dark'] .dataset-title,
        [data-theme='dark'] .method-title {
          color: var(--text-primary) !important;
        }

        [data-theme='dark'] .method-description {
          color: var(--text-secondary) !important;
        }

        [data-theme='dark'] .badge-supervised {
          background: #1e40af !important;
          color: #dbeafe !important;
        }

        [data-theme='dark'] .badge-unsupervised {
          background: #92400e !important;
          color: #fef3c7 !important;
        }

        [data-theme='dark'] .badge-network {
          background: #3730a3 !important;
          color: #e0e7ff !important;
        }

        [data-theme='dark'] .badge-recommended {
          background: #065f46 !important;
          color: #d1fae5 !important;
        }

        /* Bootstrap text color overrides for dark mode */
        [data-theme='dark'] .text-danger {
          color: #ff6b6b !important;
        }

        [data-theme='dark'] .text-success {
          color: #51cf66 !important;
        }

        [data-theme='dark'] .text-warning {
          color: #ffd43b !important;
        }

        [data-theme='dark'] .text-info {
          color: #74c0fc !important;
        }

        /* Theme-aware highlight panel (replaces inline #f8f9fa) */
        .glyco-card-highlight {
          background-color: #f8f9fa !important;
        }
        [data-theme='dark'] .glyco-card-highlight {
          background: var(--bg-secondary) !important;
        }
        .multiomics-section-tinted {
          background-color: #f8f9fa;
          border-bottom: 1px solid #e9ecef;
        }
        [data-theme='dark'] .multiomics-section-tinted {
          background: var(--bg-secondary) !important;
          border-bottom-color: var(--border-color) !important;
        }
        [data-theme='dark'] .sample-match-matrix {
          background: var(--bg-secondary) !important;
          color: var(--text-primary) !important;
          border-color: var(--border-color) !important;
        }
        [data-theme='dark'] .integration-method-card.selected {
          background: linear-gradient(135deg, rgba(102,126,234,0.25) 0%, var(--bg-secondary) 100%) !important;
          border-color: #667eea !important;
        }
        [data-theme='dark'] .status-pending {
          background: rgba(251, 191, 36, 0.3) !important;
          color: #fde68a !important;
        }
        [data-theme='dark'] .status-uploaded {
          background: rgba(34, 197, 94, 0.3) !important;
          color: #86efac !important;
        }
        [data-theme='dark'] .status-error {
          background: rgba(239, 68, 68, 0.3) !important;
          color: #fca5a5 !important;
        }

        /* Make the outer tab content transparent */
        .multiomics-tab-content {
          background: transparent !important;
        }
      ")),
        
        fluidRow(
          # Left Panel: Dataset Upload & Configuration (Reduced width)
          column(2,
                 # Load Saved Analyses Section (NEW)
                 div(class = "glyco-card",
                     div(class = "glyco-card-header",
                         h4(icon("folder-open"), " Load Saved Analyses", style = "margin: 0;")
                     ),
                     div(style = "padding: 15px; height: 800px; overflow-y: auto;",
                         helpText("Load previously saved analyses from the Data tab for N-integration, or browse for .oms, .csv, or .xlsx files (you may select multiple omics files and an optional sample metadata file)."),
