          )
        ),
        
        # Navigation tabs with modern styling
        tags$style(HTML("
        .help-about-tabs .nav-tabs {
          border-bottom: 3px solid #667eea;
          margin-bottom: 30px;
          flex-wrap: wrap;
        }
        .help-about-tabs .nav-tabs > li > a {
          color: #495057;
          font-weight: 600;
          font-size: 15px;
          padding: 12px 20px;
          border-radius: 8px 8px 0 0;
          transition: all 0.3s ease;
          border: none;
          margin-right: 5px;
        }
        .help-about-tabs .nav-tabs > li > a:hover {
          background-color: #f8f9fa;
          color: #667eea;
          border: none;
        }
        .help-about-tabs .nav-tabs > li.active > a,
        .help-about-tabs .nav-tabs > li.active > a:hover,
        .help-about-tabs .nav-tabs > li.active > a:focus {
          background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
          color: white;
          border: none;
          box-shadow: 0 4px 15px rgba(102, 126, 234, 0.4);
        }
        .help-about-content {
          background: white;
          padding: 30px;
          border-radius: 10px;
          box-shadow: 0 5px 20px rgba(0,0,0,0.08);
          min-height: 500px;
        }
        .feature-card {
          background: #f8f9fa;
          border-left: 4px solid #667eea;
          padding: 20px;
          margin-bottom: 20px;
          border-radius: 8px;
          transition: all 0.3s ease;
        }
        .feature-card:hover {
          box-shadow: 0 5px 15px rgba(0,0,0,0.1);
          transform: translateX(5px);
        }
        .feature-card h4 {
          color: #667eea;
          font-weight: 700;
          margin-bottom: 10px;
        }
        .info-section {
          margin-bottom: 35px;
        }
        .info-section h3 {
          color: #2d3748;
          font-weight: 700;
          font-size: 1.8em;
          margin-bottom: 20px;
          padding-bottom: 10px;
          border-bottom: 3px solid #667eea;
        }
        .workflow-step {
          display: flex;
          align-items: flex-start;
          margin-bottom: 25px;
          padding: 20px;
          background: linear-gradient(135deg, #f8f9fa 0%, #e9ecef 100%);
          border-radius: 8px;
        }
        .workflow-number {
          background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
          color: white;
          width: 40px;
          height: 40px;
          border-radius: 50%;
          display: flex;
          align-items: center;
          justify-content: center;
          font-weight: 700;
          font-size: 1.2em;
          margin-right: 20px;
          flex-shrink: 0;
          box-shadow: 0 4px 10px rgba(102, 126, 234, 0.3);
        }
        .workflow-content h5 {
          color: #667eea;
          font-weight: 700;
          margin-bottom: 8px;
        }
        .stats-grid {
          display: grid;
          grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
          gap: 20px;
          margin: 25px 0;
        }
        .stat-card {
          background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
          color: white;
          padding: 25px;
          border-radius: 10px;
          text-align: center;
          box-shadow: 0 5px 15px rgba(102, 126, 234, 0.3);
        }
        .stat-card h4 {
          font-size: 2.5em;
          font-weight: 700;
          margin-bottom: 10px;
          color: white;
        }
        .stat-card p {
          margin: 0;
          opacity: 0.95;
          font-size: 1.1em;
        }
      ")),
        
