# Add JavaScript for dynamic cutoff row width adjustment
tags$script(HTML("
    $(document).ready(function() {
      // Function to update cutoff row classes based on ROTS method selection
      function updateCutoffRows() {
        var isRots = $('#sig_method').val() === 'rots';
        var cutoffRowIds = [
          'diff_cutoff_row',
          'intersection_cutoff_row',
          'roc_cutoff_row',
          'heatmap_cutoff_row',
          'enrichment_cutoff_row',
          'dist_cutoff_row'
        ];

        // Handle regular cutoff rows with p-value, FDR, and Log2FC
        cutoffRowIds.forEach(function(id) {
          var element = $('#' + id);
          if (element.length > 0) {
            if (isRots) {
              element.removeClass('cutoff-row-without-fdr').addClass('cutoff-row-with-fdr');
            } else {
              element.removeClass('cutoff-row-with-fdr').addClass('cutoff-row-without-fdr');
            }
          }
        });

        // Handle Distribution Analysis Filtering Options card
        var distFilterCard = $('#dist_filtering_card');
        if (distFilterCard.length > 0) {
          if (isRots) {
            distFilterCard.show();
          } else {
            distFilterCard.hide();
          }
        }
      }

      // Update on page load
      updateCutoffRows();

      // Update when sig_method changes
      $(document).on('change', '#sig_method', function() {
        setTimeout(updateCutoffRows, 100); // Small delay to ensure Shiny updates
      });

      // Also listen for Shiny input updates
      if (window.Shiny) {
        Shiny.addCustomMessageHandler('updateCutoffRows', function(message) {
          updateCutoffRows();
        });
      }
    });
  ")),

# Multi-Omics Integration Method Card Selection JavaScript
tags$script(HTML("
    // Define scroll function globally so onclick handlers can call it
    window.scrollToParams = function() {
      setTimeout(function() {
        var $divider = $('#method_params_divider');
        if ($divider.length > 0) {
          // Find the scrollable parent container (the Integration Method card)
          var $scrollContainer = $divider.closest('div[style*=\"overflow-y\"]');
          if ($scrollContainer.length > 0) {
            // Calculate position relative to the container
            var dividerPos = $divider.position().top;
            var targetScroll = dividerPos - 50; // 50px offset

            $scrollContainer.animate({
              scrollTop: targetScroll
            }, 400);
          }
        }
      }, 100);
    };

    $(document).on('shiny:connected', function() {
      // Highlight selected method card
      $(document).on('change', '#integration_method', function() {
        var selectedMethod = $(this).val();
        $('.integration-method-card').removeClass('selected');
        if (selectedMethod) {
          $('#method_' + selectedMethod).addClass('selected');
        }
      });

      // Update dataset status badges
      window.updateDatasetStatus = function(dataset, status) {
        var badge = $('#' + dataset + '_status');
        var card = $('#' + dataset + '_card');

        badge.removeClass('status-pending status-uploaded status-error');
        card.removeClass('uploaded error');

        if (status === 'uploaded') {
          badge.addClass('status-uploaded').text('✓ Uploaded');
          card.addClass('uploaded');
        } else if (status === 'error') {
          badge.addClass('status-error').text('✗ Error');
          card.addClass('error');
        } else {
          badge.addClass('status-pending').text('Pending');
        }
      };

      // Smooth scroll to results when integration runs
      $(document).on('click', '#run_integration', function() {
        setTimeout(function() {
          $('html, body').animate({
            scrollTop: $('#multiomics_results_tabs').offset().top - 100
          }, 500);
        }, 500);
      });

      // Handle dataset status updates
      if (window.Shiny && window.Shiny.addCustomMessageHandler) {
        Shiny.addCustomMessageHandler('updateDatasetStatus', function(message) {
          window.updateDatasetStatus(message.dataset, message.status);
        });
      }
    });
  "))
),  # Close navbarPage

