# Jibosky JavaScript Handler
tags$script(HTML("
  $(document).ready(function() {
    var chatWindow = $('#jibosky-chat-window');
    var chatButton = $('#jibosky-chat-button');
    var isOpen = false;

    $('#jibosky-chat-button, .jibosky-close-btn').on('click', function() {
      isOpen = !isOpen;
      if (isOpen) {
        chatWindow.addClass('show');
      } else {
        chatWindow.removeClass('show');
      }
    });

    // Auto-scroll to bottom when new messages arrive
    var messagesContainer = $('#jibosky-messages');
    var observer = new MutationObserver(function() {
      messagesContainer.scrollTop(messagesContainer[0].scrollHeight);
    });

    if (messagesContainer.length > 0) {
      observer.observe(messagesContainer[0], { childList: true, subtree: true });
    }

    // Custom message handler for UI state changes
    Shiny.addCustomMessageHandler('jibosky_ui_state', function(message) {
      var btn = document.getElementById('jibosky-send-button');
      var input = document.getElementById('jibosky-input');

      if (message.action === 'disable') {
        input.disabled = true;
        input.placeholder = message.placeholder;
        btn.setAttribute('data-mode', 'stop');
        btn.innerHTML = '&#x23F9;';  // Stop square icon
        btn.style.backgroundColor = '#dc3545';  // Red color for stop
      } else if (message.action === 'enable') {
        input.disabled = false;
        input.placeholder = message.placeholder;
        btn.setAttribute('data-mode', 'send');
        btn.innerHTML = '&#x27A4;';  // Arrow icon
        btn.style.backgroundColor = '';  // Reset to default color
        input.focus();
      }
    });
  });
")),

# Microphone Speech Recognition Script
tags$script(HTML("
      var jibosky_recognition = null;
      var jibosky_isRecording = false;
      var jibosky_recognitionSupported = false;

      // Initialize speech recognition when document is ready
      $(document).ready(function() {
        var SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;

        if (!SpeechRecognition) {
          console.warn('Speech recognition not supported in this browser');
          jibosky_recognitionSupported = false;
          return;
        }

        try {
          jibosky_recognitionSupported = true;
          jibosky_recognition = new SpeechRecognition();
          jibosky_recognition.continuous = false;
          jibosky_recognition.interimResults = true;
          jibosky_recognition.lang = 'en-US';
          jibosky_recognition.maxAlternatives = 1;

          console.log('Speech recognition initialized successfully');

          jibosky_recognition.onstart = function() {
            console.log('Speech recognition started');
            jibosky_isRecording = true;
            var btn = document.getElementById('jibosky-mic-button');
            if (btn) {
              btn.classList.add('recording');
              btn.innerHTML = '<i class=\"fas fa-stop\" style=\"font-size: 18px;\"></i>';
            }
          };

          jibosky_recognition.onresult = function(event) {
            console.log('Speech recognition result received');
            var transcript = '';

            for (var i = event.resultIndex; i < event.results.length; i++) {
              if (event.results[i].isFinal) {
                transcript += event.results[i][0].transcript + ' ';
              } else {
                // Show interim results
                transcript += event.results[i][0].transcript;
              }
            }

            if (transcript) {
              var input = document.getElementById('jibosky-input');
              if (input) {
                // Replace interim or add final
                if (event.results[event.resultIndex].isFinal) {
                  input.value += transcript;
                } else {
                  // For interim, we just update without saving yet
                  var currentVal = input.value;
                  if (!input.dataset.baseValue) {
                    input.dataset.baseValue = currentVal;
                  }
                  input.value = input.dataset.baseValue + transcript;
                }
                input.style.height = 'auto';
                input.style.height = Math.min(200, input.scrollHeight) + 'px';
              }
            }
          };

          jibosky_recognition.onerror = function(event) {
            console.error('Speech recognition error:', event.error);
            jibosky_isRecording = false;
            var btn = document.getElementById('jibosky-mic-button');
            if (btn) {
              btn.classList.remove('recording');
              btn.innerHTML = '<i class=\"fas fa-microphone-lines\" style=\"font-size: 18px;\"></i>';
            }

            // Show user-friendly error messages
            if (event.error === 'not-allowed' || event.error === 'service-not-allowed') {
              alert('Microphone access denied. Please allow microphone access in your browser settings.');
            } else if (event.error === 'no-speech') {
              console.log('No speech detected');
            } else if (event.error === 'network') {
              alert('Network error. Speech recognition requires internet connection.');
            }
          };

          jibosky_recognition.onend = function() {
            console.log('Speech recognition ended');
            jibosky_isRecording = false;
            var btn = document.getElementById('jibosky-mic-button');
            if (btn) {
              btn.classList.remove('recording');
              btn.innerHTML = '<i class=\"fas fa-microphone-lines\" style=\"font-size: 18px;\"></i>';
            }
            // Clear the interim base value
            var input = document.getElementById('jibosky-input');
            if (input) {
              delete input.dataset.baseValue;
            }
          };

        } catch (error) {
          console.error('Error initializing speech recognition:', error);
          jibosky_recognitionSupported = false;
        }
      });

      // Toggle microphone function (called from button onclick)
      window.jibosky_toggleMicrophone = function() {
        console.log('Toggle microphone called. Supported:', jibosky_recognitionSupported, 'Recording:', jibosky_isRecording);

        if (!jibosky_recognitionSupported) {
          alert('Speech recognition is not supported in your browser.\\n\\nPlease use:\\n- Chrome or Edge (recommended)\\n- Safari (Mac/iOS)\\n\\nNote: Speech recognition requires HTTPS or localhost.');
          return;
        }

        if (!jibosky_recognition) {
          alert('Speech recognition not initialized. Please refresh the page.');
          return;
        }

        if (jibosky_isRecording) {
          console.log('Stopping recording');
          try {
            jibosky_recognition.stop();
          } catch (error) {
            console.error('Error stopping recognition:', error);
          }
        } else {
          console.log('Starting recording');
          var input = document.getElementById('jibosky-input');

          try {
            jibosky_recognition.start();
          } catch (error) {
            console.error('Error starting recognition:', error);
            alert('Failed to start microphone: ' + error.message);
          }
        }
      };

      // Hold-to-record functionality
      window.jibosky_startMicrophoneHold = function(event) {
        if (!jibosky_recognitionSupported || !jibosky_recognition) return;
        if (event.button !== 0 && event.type === 'mousedown') return; // Only left mouse button

        if (!jibosky_isRecording) {
          console.log('Starting hold recording');
          try {
            jibosky_recognition.start();
          } catch (error) {
            console.error('Error starting hold recording:', error);
          }
        }
      };

      window.jibosky_stopMicrophoneHold = function() {
        if (!jibosky_recognitionSupported || !jibosky_recognition) return;

        if (jibosky_isRecording) {
          console.log('Stopping hold recording');
          try {
            jibosky_recognition.stop();
          } catch (error) {
            console.error('Error stopping hold recording:', error);
          }
        }
      };
    ")),

